import{_ as i,o as e,a as l,a3 as t}from"./chunks/framework.CnT1yzXN.js";const p=JSON.parse('{"title":"Анализатор логов","description":"Умный анализатор логов Minecraft. Автоматический поиск причин крашей, определение виноватых модов и предложение решений.","frontmatter":{"description":"Умный анализатор логов Minecraft. Автоматический поиск причин крашей, определение виноватых модов и предложение решений.","head":[["meta",{"name":"keywords","content":"minecraft crash analyzer, stuzhik, стужик, анализ логов minecraft, почему вылетает minecraft, minecraft crash fix"}]]},"headers":[],"relativePath":"guide/log-analyzer.md","filePath":"guide/log-analyzer.md"}'),o={name:"guide/log-analyzer.md"};function r(n,a,s,d,c,h){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="анализатор-логов" tabindex="-1">Анализатор логов <a class="header-anchor" href="#анализатор-логов" aria-label="Permalink to &quot;Анализатор логов&quot;">​</a></h1><h2 id="автоматическии-анализ" tabindex="-1">Автоматический анализ <a class="header-anchor" href="#автоматическии-анализ" aria-label="Permalink to &quot;Автоматический анализ&quot;">​</a></h2><p>При краше игры:</p><ol><li>Stuzhik автоматически откроет анализатор</li><li>Покажет найденные проблемы</li><li>Для каждой - возможные решения</li><li>Кнопки для автоисправления (где возможно)</li></ol><h2 id="ручнои-анализ" tabindex="-1">Ручной анализ <a class="header-anchor" href="#ручнои-анализ" aria-label="Permalink to &quot;Ручной анализ&quot;">​</a></h2><p>Если нужно проанализировать вручную:</p><ol><li>Открой экземпляр</li><li>Кнопка &quot;Анализ логов&quot;</li><li>Выбери тип лога: <ul><li><code>crash-report</code> - последний краш</li><li><code>latest.log</code> - текущая сессия</li><li>Выбрать файл вручную</li></ul></li></ol><h2 id="типы-проблем" tabindex="-1">Типы проблем <a class="header-anchor" href="#типы-проблем" aria-label="Permalink to &quot;Типы проблем&quot;">​</a></h2><h3 id="critical-критичные" tabindex="-1">Critical (Критичные) <a class="header-anchor" href="#critical-критичные" aria-label="Permalink to &quot;Critical (Критичные)&quot;">​</a></h3><p>Полностью блокируют запуск:</p><table tabindex="0"><thead><tr><th>Проблема</th><th>Причина</th><th>Решение</th></tr></thead><tbody><tr><td>Java version mismatch</td><td>Неправильная версия Java</td><td>Stuzhik установит нужную</td></tr><tr><td>Missing dependency</td><td>Отсутствует нужный мод</td><td>Автоустановка</td></tr><tr><td>Mod conflict</td><td>Несовместимые моды</td><td>Удалить один из модов</td></tr></tbody></table><h3 id="high-высокие" tabindex="-1">High (Высокие) <a class="header-anchor" href="#high-высокие" aria-label="Permalink to &quot;High (Высокие)&quot;">​</a></h3><p>Вызывают краш во время игры:</p><ul><li>OutOfMemoryError</li><li>Mixin conflicts</li><li>ClassNotFoundException</li><li>NullPointerException в моде</li></ul><h3 id="medium-средние" tabindex="-1">Medium (Средние) <a class="header-anchor" href="#medium-средние" aria-label="Permalink to &quot;Medium (Средние)&quot;">​</a></h3><p>Могут вызвать проблемы:</p><ul><li>Deprecated warnings</li><li>Config errors</li><li>Missing textures/models</li></ul><h3 id="low-низкие" tabindex="-1">Low (Низкие) <a class="header-anchor" href="#low-низкие" aria-label="Permalink to &quot;Low (Низкие)&quot;">​</a></h3><p>Не влияют на игру:</p><ul><li>Info сообщения</li><li>Debug логи</li><li>Performance warnings</li></ul><h2 id="решения" tabindex="-1">Решения <a class="header-anchor" href="#решения" aria-label="Permalink to &quot;Решения&quot;">​</a></h2><h3 id="автоматические" tabindex="-1">Автоматические <a class="header-anchor" href="#автоматические" aria-label="Permalink to &quot;Автоматические&quot;">​</a></h3><p>Кнопка &quot;Применить&quot; для:</p><p><strong>Удаление мода:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>Удалить problematic_mod.jar</span></span></code></pre></div><p><strong>Увеличение памяти:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>Было: 2GB → Стало: 4GB</span></span></code></pre></div><p><strong>Установка зависимости:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>Установить fabric-api-0.92.0.jar</span></span></code></pre></div><p><strong>Изменение конфига:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>config/mod.toml: option = false → true</span></span></code></pre></div><h3 id="ручные" tabindex="-1">Ручные <a class="header-anchor" href="#ручные" aria-label="Permalink to &quot;Ручные&quot;">​</a></h3><p>Пошаговая инструкция:</p><ol><li>Скачай мод X версии Y</li><li>Удали старую версию</li><li>Положи новую в mods/</li><li>Перезапусти</li></ol><h2 id="live-мониторинг" tabindex="-1">Live мониторинг <a class="header-anchor" href="#live-мониторинг" aria-label="Permalink to &quot;Live мониторинг&quot;">​</a></h2><h3 id="включение" tabindex="-1">Включение <a class="header-anchor" href="#включение" aria-label="Permalink to &quot;Включение&quot;">​</a></h3><ol><li>Запусти экземпляр</li><li>Stuzhik автоматически начнёт мониторинг</li><li>Индикатор в header покажет статус</li></ol><h3 id="события" tabindex="-1">События <a class="header-anchor" href="#события" aria-label="Permalink to &quot;События&quot;">​</a></h3><p><strong>Warning:</strong> Предупреждения из лога</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>[Sodium] Incompatible mixin detected</span></span></code></pre></div><p><strong>Error:</strong> Ошибки без краша</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>[KubeJS] Script error in startup.js:15</span></span></code></pre></div><p><strong>Crash:</strong> Полный краш</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>Game crashed! Analyzing...</span></span></code></pre></div><h3 id="уведомления" tabindex="-1">Уведомления <a class="header-anchor" href="#уведомления" aria-label="Permalink to &quot;Уведомления&quot;">​</a></h3><p>При обнаружении проблемы:</p><ol><li>Всплывающее уведомление</li><li>Список проблем в live panel</li><li>Кнопки для исправления</li></ol><h2 id="база-знании" tabindex="-1">База знаний <a class="header-anchor" href="#база-знании" aria-label="Permalink to &quot;База знаний&quot;">​</a></h2><h3 id="обучение" tabindex="-1">Обучение <a class="header-anchor" href="#обучение" aria-label="Permalink to &quot;Обучение&quot;">​</a></h3><p>Когда применяешь решение:</p><ol><li>Stuzhik сохраняет результат</li><li>&quot;Помогло&quot; / &quot;Не помогло&quot;</li><li>Success rate обновляется</li></ol><h3 id="персонализация" tabindex="-1">Персонализация <a class="header-anchor" href="#персонализация" aria-label="Permalink to &quot;Персонализация&quot;">​</a></h3><p>Решения ранжируются:</p><table tabindex="0"><thead><tr><th>Решение</th><th>Success Rate</th><th>Показывать</th></tr></thead><tbody><tr><td>Удалить мод</td><td>95%</td><td>✅ Первым</td></tr><tr><td>Обновить</td><td>70%</td><td>✅ Вторым</td></tr><tr><td>Изменить конфиг</td><td>30%</td><td>⚠️ С предупреждением</td></tr></tbody></table><h2 id="экспорт" tabindex="-1">Экспорт <a class="header-anchor" href="#экспорт" aria-label="Permalink to &quot;Экспорт&quot;">​</a></h2><h3 id="для-отчета" tabindex="-1">Для отчёта <a class="header-anchor" href="#для-отчета" aria-label="Permalink to &quot;Для отчёта&quot;">​</a></h3><p>Кнопки анализатора после анализа:</p><ul><li>&quot;Экспорт&quot; — отчёт анализа в <code>.json</code> (открыть его снова можно кнопкой &quot;Импорт&quot;)</li><li>&quot;Копировать как Markdown&quot; — отчёт в буфер обмена, чтобы вставить в чат или на GitHub</li></ul><h3 id="для-поддержки" tabindex="-1">Для поддержки <a class="header-anchor" href="#для-поддержки" aria-label="Permalink to &quot;Для поддержки&quot;">​</a></h3><p>При обращении к автору мода:</p><ol><li>Кнопка &quot;Архив&quot; (есть у экземпляра) — сохраняет <code>.zip</code></li><li>Включает: <ul><li><code>latest.log</code> и конец <code>debug.log</code></li><li>Последние краш-репорты (до 5)</li><li>Анализ Stuzhik</li><li>Название экземпляра</li></ul></li><li>Прикрепи в <a href="https://t.me/stuzhik_launcher" target="_blank" rel="noreferrer">Telegram</a></li></ol><h2 id="паттерны-ошибок" tabindex="-1">Паттерны ошибок <a class="header-anchor" href="#паттерны-ошибок" aria-label="Permalink to &quot;Паттерны ошибок&quot;">​</a></h2><p>Stuzhik распознаёт ~50 типов ошибок:</p><h3 id="java" tabindex="-1">Java <a class="header-anchor" href="#java" aria-label="Permalink to &quot;Java&quot;">​</a></h3><ul><li>OutOfMemoryError</li><li>StackOverflowError</li><li>UnsupportedClassVersionError</li><li>NoClassDefFoundError</li></ul><h3 id="minecraft" tabindex="-1">Minecraft <a class="header-anchor" href="#minecraft" aria-label="Permalink to &quot;Minecraft&quot;">​</a></h3><ul><li>Missing registry entries</li><li>Invalid block states</li><li>Corrupted chunk data</li><li>Missing textures</li></ul><h3 id="моды" tabindex="-1">Моды <a class="header-anchor" href="#моды" aria-label="Permalink to &quot;Моды&quot;">​</a></h3><ul><li>Mixin conflicts</li><li>ASM transformation failures</li><li>Config parsing errors</li><li>Dependency issues</li></ul><h3 id="загрузчики" tabindex="-1">Загрузчики <a class="header-anchor" href="#загрузчики" aria-label="Permalink to &quot;Загрузчики&quot;">​</a></h3><ul><li>Forge mod on Fabric</li><li>Missing Fabric API</li><li>Incompatible loader version</li></ul>',71)])])}const b=i(o,[["render",r]]);export{p as __pageData,b as default};
